"""Domain migration helper (temporary): who fetches the subscription through which host, and - when switched on - the headers that tell the apps the new address.

Why in the panel and not in nginx: HAProxy sends every request for the panel paths straight to the panel (backend `hiddifypanel`), nginx never sees them.

Settings: /opt/hiddify-manager/cabinet/migration.json (re-read when the file changes, no restart; a missing or broken file = everything off)
  log          true = write one line per subscription request to LOG (time, first 8 characters of the account uuid, host, User-Agent, status, tail of the path; no IP address)
  old_hosts    hosts of the OLD subscription address, e.g. ["old.example"]
  new_host     the new subscription host (no scheme, no path)
  headers      true = answer requests that come in on an old host (status 200) with
                 moved-permanently-to: https://<new_host><same path>   (Hiddify app: replaces the stored subscription URL)
                 new-domain: <new_host>                               (Happ: changes only the domain; an advanced header, the response carries the Happ provider id)
                 fallback-url: https://<new_host><same path>          (Happ: the address it switches to when the main one stops answering)
  notice       true = (same accounts / old hosts as "headers", status 200) the apps are TOLD in words: profile title, announcement + button (Happ, INCY), the "open web page" button
               points to the new cabinet, and a first line "address changed" in the plain-text server list (V2RayTun, Happ, INCY main link). Nothing is added to JSON lists.
  only         TEST MODE: a list of the first 8 characters of account uuids; when the key is there, ONLY those accounts get the headers (an empty or mistyped list = nobody; the log stays for everybody)
Nothing here may ever break a request: every error is swallowed."""
from __future__ import annotations

import base64
import json
import os
import re
import threading
import time
from urllib.parse import quote

from flask import request

CONF = os.environ.get("SUBWATCH_CONF", "/opt/hiddify-manager/cabinet/migration.json")
LOG = os.environ.get("SUBWATCH_LOG", "/opt/hiddify-manager/hiddify-panel/var/sub-watch.log")
MAX_LOG_BYTES = 5 * 1024 * 1024
HOST_RE = re.compile(r"^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$")
# /<path>/<uuid>[/tail]: the first segment is the client (or admin) path, the uuid is the account
SUB_RE = re.compile(r"^/([^/]+)/([0-9a-f]{8})(-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})(/.*)?$")
SKIP_TAILS = ("/admin", "/api", "/static")
NOTICE_TITLE = "⚠ Новая ссылка в боте"
NOTICE_TEXT = "Адрес подписки изменился. Откройте «Личный кабинет» в боте (или кнопку «Открыть страницу»), скопируйте новую ссылку и вставьте её вместо старой."
NOTICE_LINE = "⚠ Адрес подписки изменился: возьмите новую ссылку в личном кабинете (бот)"
NOTICE_BUTTON = "Новая ссылка"
NL = chr(10)
SCHEME_LINE = re.compile(r"^[a-z][a-z0-9+.-]*://", re.I)


def _b64(s: str) -> str:
    return "base64:" + base64.b64encode(s.encode("utf-8")).decode("ascii")

_lock = threading.Lock()
_cache = {"mtime": None, "conf": {}}


def _conf() -> dict:
    try:
        m = os.stat(CONF).st_mtime_ns
    except OSError:
        _cache.update(mtime=None, conf={})
        return {}
    if m != _cache["mtime"]:
        conf = {}
        try:
            with open(CONF, "r", encoding="utf-8") as fh:
                raw = json.load(fh)
            if isinstance(raw, dict):
                conf["log"] = raw.get("log") is True
                conf["headers"] = raw.get("headers") is True
                conf["notice"] = raw.get("notice") is True
                conf["old_hosts"] = [h for h in (str(x).strip().lower() for x in raw.get("old_hosts") or []) if HOST_RE.match(h)]
                nh = str(raw.get("new_host") or "").strip().lower()
                conf["new_host"] = nh if HOST_RE.match(nh) else ""
                # test mode fails CLOSED: when "only" is in the file but holds no valid entry (a typo), nobody gets the headers
                conf["only"] = [u for u in (str(x).strip().lower() for x in raw.get("only") or []) if re.match(r"^[0-9a-f]{8}$", u)] if "only" in raw else None
        except Exception:  # noqa: BLE001 - a broken file means "off"
            conf = {}
        _cache.update(mtime=m, conf=conf)
    return _cache["conf"]


def _write(line: str) -> None:
    with _lock:
        try:
            if os.path.getsize(LOG) > MAX_LOG_BYTES:
                os.replace(LOG, LOG + ".1")
        except OSError:
            pass
        with open(LOG, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")


def _after_request(resp):
    try:
        conf = _conf()
        if not conf or not (conf.get("log") or conf.get("headers") or conf.get("notice")):
            return resp
        m = SUB_RE.match(request.path)
        if not m:
            return resp
        seg, u8, rest, tail = m.group(1), m.group(2), m.group(3), m.group(4) or "/"
        if tail.startswith(SKIP_TAILS):
            return resp
        host = (request.host or "").split(":")[0].lower()
        if conf.get("log"):
            ua = re.sub(r"[^ -~]", "?", request.headers.get("User-Agent", ""))[:120].replace('"', "'")
            _write(f'{time.strftime("%Y-%m-%dT%H:%M:%S%z")} {u8} {host} "{ua}" {resp.status_code} "{tail[:40]}"')
        only = conf.get("only")
        moved = (conf.get("new_host") and host in conf.get("old_hosts", []) and resp.status_code == 200 and (only is None or u8 in only))
        if moved and conf.get("headers"):
            resp.headers["moved-permanently-to"] = f"https://{conf['new_host']}{request.path}"
            resp.headers["new-domain"] = conf["new_host"]
            resp.headers["fallback-url"] = f"https://{conf['new_host']}{request.path}"
        if moved and conf.get("notice"):
            cab = f"https://{conf['new_host']}/{seg}/{u8}{rest}/"        # the cabinet of this account on the new host
            resp.headers["profile-title"] = _b64(NOTICE_TITLE)
            resp.headers["profile-web-page-url"] = cab
            resp.headers["announce"] = _b64(NOTICE_TEXT)                # Happ, INCY
            resp.headers["announce-url"] = cab                          # INCY
            resp.headers["sub-info-text"] = _b64(NOTICE_TEXT)           # Happ (advanced: only with the provider id, i.e. on the /happ/ link)
            resp.headers["sub-info-color"] = "red"
            resp.headers["sub-info-button-text"] = _b64(NOTICE_BUTTON)
            resp.headers["sub-info-button-link"] = cab
            if (resp.mimetype or "").startswith("text/plain") and not resp.direct_passthrough:
                body = resp.get_data(as_text=True)
                line = f"trojan://1@new-link.notice:1?sni=fake_ip_for_sub_link&security=tls#{quote(NOTICE_LINE)}"
                first = next((ln for ln in body.splitlines() if ln.strip()), "")
                if SCHEME_LINE.match(first):                              # a plain list of links
                    resp.set_data(line + NL + body)
                else:                                                     # the usual form: the same list as one base64 text
                    try:
                        plain = base64.b64decode("".join(body.split()) + "=" * (-len("".join(body.split())) % 4), validate=True).decode("utf-8")
                    except Exception:  # noqa: BLE001 - JSON or anything else: left alone
                        plain = ""
                    if SCHEME_LINE.match(next((ln for ln in plain.splitlines() if ln.strip()), "")):
                        resp.set_data(base64.b64encode((line + NL + plain).encode("utf-8")).decode("ascii"))
    except Exception:  # noqa: BLE001 - never break a request
        pass
    return resp


def init_app(app) -> None:
    app.after_request(_after_request)
